<?php
declare(strict_types=1);
require __DIR__ . '/bootstrap.php';
use Dilemma\{Auth, Connections, Db, Debates, DebateActions, ReadModel, Support, Views};
$a = user_fixture('OpenA'); $b = user_fixture('OpenB'); $c = user_fixture('OpenC');
function question(array $actor, string $mode = 'open', bool $public = true): array {
	return Debates::create($actor, ['idempotency_key' => Support::token(), 'title' => 'Should cities ban cars from the centre?', 'stance' => 'Streets should be for people, not private cars.', 'opponent_mode' => $mode, 'public_consent' => $public, 'processing_consent' => true]);
}
$input = ['idempotency_key' => Support::token(), 'stance' => 'People still need access by car.', 'accept_terms' => true, 'processing_consent' => true, 'public_consent' => true];
$private = question($a['actor'], 'invite');
rejects(fn () => Debates::readable($private['debate_id']), 404, 'Friend question stays unlisted even with creator publication consent');
rejects(fn () => question($a['actor'], 'open', false), 422, 'Open question requires explicit publication consent');
$open = question($a['actor']); $id = $open['debate_id'];
check(Debates::readable($id)['is_public'] && in_array($id, array_column(ReadModel::list(['status' => 'open'])['items'], 'id')), 'Open question is publicly readable and listed');
$html = Views::page('/debate/' . $id, null, null);
check(str_contains($html, 'data-auth-return="/debate/' . $id . '#join"') && !str_contains($html, 'Authorization: Bearer'), 'Public join page preserves login return without exposing access');
$setup = Connections::current($a['actor'], $id);
preg_match('/Authorization: Bearer ([A-Za-z0-9_-]{43})/', $setup['setup_text'], $m);
$agent = Connections::authenticate('Bearer ' . $m[1]);
rejects(fn () => Debates::claim($agent, $id, $input), 403, 'Agent cannot claim opponent slot');
rejects(fn () => Debates::claim($a['actor'], $id, $input), 403, 'Creator cannot claim own opponent slot');
rejects(fn () => Debates::claim($b['actor'], $id, array_replace($input, ['public_consent' => false])), 422, 'Joining open question requires explicit consent');
$joined = Debates::claim($b['actor'], $id, $input);
check(Debates::row($id)['status'] === 'active' && count(ReadModel::participants($id)) === 2, 'First human joins and activates the debate');
check(Debates::claim($b['actor'], $id, $input) === array_replace($joined, ['idempotent_replay' => true]), 'Identical claim returns persisted receipt');
rejects(fn () => Debates::claim($c['actor'], $id, $input), 409, 'Later claimant cannot take occupied slot', 'opponent_taken');
check(Connections::current($a['actor'], $id) === $setup && Connections::current($b['actor'], $id)['persistent'], 'Joining retains creator access and creates separate permanent opponent access');
DebateActions::apply($b['actor'], $id, ['action' => 'consent', 'public_consent' => false, 'revision' => $joined['revision'], 'idempotency_key' => Support::token()]);
rejects(fn () => Debates::readable($id), 404, 'Withdrawing consent after joining makes debate private');
$closed = question($a['actor']);
DebateActions::apply($a['actor'], $closed['debate_id'], ['action' => 'close_listing', 'revision' => 1, 'idempotency_key' => Support::token()]);
rejects(fn () => Debates::readable($closed['debate_id']), 404, 'Closing public listing hides it');
rejects(fn () => Debates::claim($b['actor'], $closed['debate_id'], $input), 409, 'Closed question cannot be claimed');
$withdrawn = question($a['actor']);
DebateActions::apply($a['actor'], $withdrawn['debate_id'], ['action' => 'consent', 'public_consent' => false, 'revision' => 1, 'idempotency_key' => Support::token()]);
check(Debates::row($withdrawn['debate_id'])['status'] === 'draft', 'Withdrawing publication also closes waiting listing');
$hidden = question($a['actor']); Db::run('UPDATE debates SET hidden = 1 WHERE id = ?', [$hidden['debate_id']]);
rejects(fn () => Debates::claim($b['actor'], $hidden['debate_id'], $input), 409, 'Moderated question cannot be claimed');
$invite = Debates::invite($a['actor'], $private['debate_id'], ['idempotency_key' => Support::token()]);
DebateActions::apply($a['actor'], $private['debate_id'], ['action' => 'open_listing', 'public_consent' => true, 'revision' => 2, 'idempotency_key' => Support::token()]);
check(Debates::readable($private['debate_id'])['is_public'], 'Owner can explicitly open an existing private question');
rejects(fn () => Debates::accept($b['actor'], $input + ['token' => parse_url($invite['invitation_url'], PHP_URL_FRAGMENT)]), 404, 'Old private invitation is invalidated when opening question');
$link = Debates::invite($a['actor'], $private['debate_id'], ['idempotency_key' => Support::token()]);
check($link['invitation_url'] === \Dilemma\Config::url('/debate/' . $private['debate_id']) && $link['expires_in'] === null, 'Open question shares its durable public URL');
Auth::request_link(['email' => $c['email'], 'return_to' => '/debate/' . $private['debate_id'] . '#join'], 'open-return-' . $run);
$record = Db::one('SELECT return_target FROM email_verifications WHERE user_id = ? ORDER BY expires_at DESC LIMIT 1', [$c['actor']['user_id']]);
check(Support::unseal($record['return_target']) === '/debate/' . $private['debate_id'] . '#join', 'Magic link preserves intended debate destination');
Db::run("UPDATE users SET status = 'blocked' WHERE id = ?", [$a['actor']['user_id']]);
rejects(fn () => Debates::claim($b['actor'], $private['debate_id'], $input), 409, 'Blocked creator cannot receive a new opponent');
$deleted = question($c['actor']);
\Dilemma\Accounts::delete($c['actor'], ['confirm' => true, 'email' => $c['email']]);
check(Debates::row($deleted['debate_id'])['status'] === 'ended', 'Account deletion ends an unclaimed open question');
rejects(fn () => Debates::readable($deleted['debate_id']), 404, 'Deleted creator question is no longer public');
echo 'SUCCESS: ' . $checks . " open-debate checks.\n";
